// Copies the user documentation and the Agent Skill into packages/xlvane and generates
// llms-full.txt, so that they are in the npm tarball and readable offline (docs/PLAN.md section 4,
// item 7; docs/decisions.md D-707). Run by `npm run build` in packages/xlvane. The copies are
// generated files and are not committed (.gitignore).
import { cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));

/** Documentation files for users of the packages, in the order of llms-full.txt. */
export const DOCS = ['errors.md', 'inspect-json.md', 'cli-json.md', 'exceljs-compat.md'];

/** Writes docs/, skills/ and llms-full.txt into `target` (default packages/xlvane). */
export async function packageDocs(target = join(root, 'packages/xlvane')) {
  await rm(join(target, 'docs'), { recursive: true, force: true });
  await rm(join(target, 'skills'), { recursive: true, force: true });
  await mkdir(join(target, 'docs'), { recursive: true });
  for (const file of DOCS) await cp(join(root, 'docs', file), join(target, 'docs', file));
  await cp(join(root, 'docs/cli-json'), join(target, 'docs/cli-json'), { recursive: true });
  await cp(join(root, 'skills'), join(target, 'skills'), { recursive: true });

  const pkg = JSON.parse(await readFile(join(root, 'packages/xlvane/package.json'), 'utf8'));
  const parts = [
    `# xlvane ${pkg.version}: documentation in one file`,
    '',
    'This file joins the README of the xlvane package, the Agent Skill and the documentation in docs/. It is generated by scripts/package-docs.mjs; the separate files are in the same package.',
  ];
  const add = async (label, path) => {
    parts.push('', `<!-- file: ${label} -->`, '', (await readFile(path, 'utf8')).trim());
  };
  await add('README.md', join(root, 'packages/xlvane/README.md'));
  await add('skills/xlvane/SKILL.md', join(root, 'skills/xlvane/SKILL.md'));
  for (const file of DOCS) await add(`docs/${file}`, join(root, 'docs', file));
  for (const file of (await readdir(join(root, 'docs/cli-json'))).sort()) await add(`docs/cli-json/${file}`, join(root, 'docs/cli-json', file));
  await writeFile(join(target, 'llms-full.txt'), `${parts.join('\n')}\n`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  packageDocs().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}
